@router.get('/api/documents/{doc_id}/versions/{version_num}')
async def download_document_version(
    doc_id: int,
    version_num: int,
    db: AsyncSession = Depends(get_async_session),
    user: User = Depends(get_current_user)
):
    doc_stmt = select(Document).where(Document.id == doc_id, Document.user_id == user.id)
    doc_res = await db.execute(doc_stmt)
    if not doc_res.scalar_one_or_none():
        raise HTTPException(status_code=404, detail="Document not found")

    stmt = select(DocumentVersion).where(
        DocumentVersion.document_id == doc_id,
        DocumentVersion.version_number == version_num
    )
    result = await db.execute(stmt)
    version_entry = result.scalar_one_or_none()
    if not version_entry:
        raise HTTPException(status_code=404, detail="Version revision not found")

    return FileResponse(path=version_entry.storage_path, filename=version_entry.original_filename)
